   sk:{lines:[["T","Good morning, Alya. Come in and sit down."],["S","Good morning, Miss."],["T","Put your bag under your desk, please."],["S","Okay, Miss."],["T","Hurry up now, Raka. We're starting soon."]],note:"Use names. Children this age like being greeted one by one."},
   st:{lines:[["T","Come on in, everyone. Take your seats."],["S","Miss, can I leave my bag here?"],["T","Sure. Hang it on the hook at the back."],["S","It's raining. Can I keep my jacket on?"],["T","Of course. Close the door behind you, please."]],note:"Teach the student questions (Can I…? Is it OK if…?) so teens can manage themselves in English."},
   sp:{lines:[["T","In you come, guys. Grab a seat anywhere."],["S","Is it OK if I leave my helmet by the door?"],["T","That's fine. Just don't block the doorway."],["S","Sorry, Mr Dani. The lift was really slow."],["T","No worries. Get a move on, though. We're about to start."]],note:"Teen+ can handle idiomatic forms like In you come and Get a move on."}
