/* Additions (not from the book): rewards and consequences, using board stars and class points */
R.j5 = {title:"Giving rewards", phrases:["Well done! That's a star for your team.","You've earned a point."], tip:"", mistakes:[],
 levels:{
  ls:{lines:[["T","Wow, Alya! You sat so nicely. A star for you! (draws a big star on the board)"],["S","Star!"],["T","Let's count our stars. One, two, three!"],["S","Three stars!"]],note:"Draw the star big and count together. Young children love watching the stars grow."},
  sk:{lines:[["T","Team Tigers, you all spoke English. That's a star for your team!"],["S","Yay!"],["T","Raka, you helped Nadia. That's a point for helping others."],["S","Thank you, Miss!"],["T","When we get ten stars, we'll play a game."]],note:"Always say why the star or point is given, so children know what to do again."},
  st:{lines:[["T","Let's check the points chart. This group has twelve points for teamwork."],["S","Can we get one more for finishing first?"],["T","Finishing first isn't the goal. Do it carefully and you'll earn one."],["S","OK, we'll check our answers again."]],note:"Reward quality and effort, not just speed."},
  sp:{lines:[["T","I'm giving the whole class five class points for that discussion. Everyone contributed."],["S","Does that count towards the movie afternoon?"],["T","It does. You're at 85 out of 100. You're on a roll!"],["S","Nice!"]],note:"Older teens usually respond better to class goals than to individual stars."}
 }};
R.j6 = {title:"Giving consequences", phrases:["This is your first warning.","If you keep talking, your team will lose a star."], tip:"", mistakes:[],
 levels:{
  ls:{lines:[["T","Raka, gentle hands, please. That's one warning. (holds up one finger)"],["A","Raka stops."],["T","Thank you. Good choice! Now you can get a star."]],note:"Short words, a calm voice, and quick praise as soon as the child makes a good choice."},
  sk:{lines:[["T","Kenzo, this is your second warning. If you keep talking, your team will lose a star."],["S","Sorry, Miss."],["T","Thank you. Show me good choices and you can earn it back."]],note:"Make the consequence clear before you use it, and give a way to earn it back."},
  st:{lines:[["T","Lena, I've asked you twice to put your phone away. You've lost a point."],["S","But I was only checking the time!"],["T","We can talk about it after class. For now, phone in your bag, please."]],note:"Don't argue in front of the class. Postpone the discussion until later."},
  sp:{lines:[["T","Bima, could you stay behind for a minute, please?"],["T","Can you tell me what happened during the group task?"],["S","I didn't do my part. Sorry."],["T","Thanks for being honest. What will you do differently next time?"],["S","I'll prepare before the lesson."],["T","Good. Fresh start on Thursday."]],note:"With teens, a short private conversation works better than a public consequence."}
 }};

BOOK.j5 = {groups:[
  ["Well done! That's a star for your team.","You get a star on the board.","Let's give this team a star.","One star for Team Tigers!","Everyone in this row gets a star.","I'll put a star next to your name."],
  ["You've earned a point.","That's a point for helping others.","A point for teamwork!","I'm giving the whole class a point.","Let's add it to the points chart!","Who do you think deserves a point today?"],
  ["This star is for speaking English all the time.","You got a point because you helped Raka.","That's for working so quietly.","Great teamwork earns a star.","I'm giving you a point for trying, not just for the right answer.","You listened really carefully. That deserves a star."],
  ["Let's count the stars.","How many stars does each team have?","Team A has five stars and Team B has four.","Let's check our points for today.","The class has reached 50 points!","Which team is the winner this week?"],
  ["When we reach ten stars, we'll play a game.","Ten stars means five minutes of free choice.","If the class gets 100 points, we'll have a party.","The team with the most stars chooses the song.","You can swap your points for a sticker."]],
 notes:[
  [1,"P","Reward behaviour and effort, not only correct answers. Give the star straight away, and use the same signal every time, for example drawing the star while you say the team's name.",[]],
  [1,"L","Useful collocations:",["to give/award a star or a point","to earn/get a star or a point","to lose a star or a point","a star chart, a sticker, a stamp, a reward"]],
  [1,"S","Encourage students to react in English:",["Yay!","Thank you, Miss/Sir!","How many stars do we have?","Can we get another star?"]],
  [2,"L","If you use a class points app (for example, ClassDojo), these phrases are useful:",["Let me open the points app.","I'll show the points on the screen.","Look at your monster/avatar!","Your parents can see your points too."]],
  [2,"P","Keep points positive and quick. Award points for clear skills that the class knows, such as Helping others, Teamwork, Speaking English and On task. Show the screen briefly instead of stopping the lesson for a long time.",[]],
  [3,"P","Name the behaviour when you give a reward. Specific praise (That's for helping Raka) tells students exactly what to repeat, while general praise (Good job) does not.",[]],
  [3,"M","Use the past tense for what the student did, and a plural after numbers.",["x:I give you one point because you are helping. / Your team get two star.","v:I'm giving you a point because you helped. / Your team gets two stars."]],
  [4,"S","Students may say:",["We have six stars!","We won!","We're nearly there!","Two more stars!"]],
  [4,"P","Count stars and check points at a fixed time, for example at the end of the lesson. It keeps the routine clear and avoids interrupting the lesson again and again.",[]],
  [5,"P","Agree on the class goal at the start of the course and make it visible, for example a star target on the board or a goal on the points chart. Choose rewards that are simple and fair, such as a game, choosing the song or free-choice time.",[]],
  [5,"I","Idiomatic praise for older learners:",["You're on a roll!","Give yourselves a pat on the back.","Keep it up and the stars will keep coming!"]],
  [5,"X","See also Unit 2, C1 (Saying yes) and C2 (Encouraging) for more phrases of praise.",[]]]};

BOOK.j6 = {groups:[
  ["This is your first warning.","That's one warning, Kenzo.","Remember our class rules.","I'm going to count to three.","Think about your choice.","If this happens again, there will be a consequence."],
  ["If you keep talking, your team will lose a star.","If it happens again, I'll have to take a star away.","You've lost a star for your team.","You've lost a point.","You'll have to finish this during the break.","You'll have to sit on your own for five minutes."],
  ["Please go and sit on the thinking chair.","Move to this table, please.","Take a minute to calm down.","Come back when you're ready to join in.","You can sit here until you're ready."],
  ["Can you tell me what happened?","Why do you think you lost the star?","What can you do differently next time?","Can you say sorry to Nadia?","Let's start again. I know you can do it.","Now you can earn the star back."],
  ["Let's have a fresh start.","Everybody starts again tomorrow.","Show me good choices and you can get a star.","I'm happy you're back with us."]],
 notes:[
  [1,"P","Many schools now say consequences rather than punishment, following a positive discipline approach. Warn first, stay calm, use few words, and talk about the behaviour, not the child (That was unkind, not You are naughty).",[]],
  [1,"L","Countdown phrases:",["One … two …","I'm waiting …","Three seconds to sit down. Three, two, one."]],
  [2,"P","Keep consequences small, fair, immediate and linked to the behaviour. Avoid taking stars from a whole team too often because of one child, as it can cause conflict in the team. An individual consequence is often fairer.",[]],
  [2,"L","If you take points away, do it sparingly and always give students a clear way to earn positive points again.",[]],
  [2,"M","Use will in the result of a first conditional, and prefer consequence to punish with children.",["x:If you talk again, your team lose a star. / I will punish you.","v:If you talk again, your team will lose a star. / There will be a consequence."]],
  [3,"S","Students may say:",["Sorry, Miss/Sir.","Can I come back now?","I'm ready now."]],
  [4,"P","Talk to the student briefly and privately after the moment, not in front of the class. If the problem is serious, use the students' mother tongue to make sure they understand.",[]],
  [4,"X","See also Unit 3, B4 (Coping with problems).",[]],
  [5,"P","Always reconnect after a consequence. Notice and praise the student's next good choice quickly, so the relationship stays positive.",[]],
  [5,"I","Idiomatic phrases for older learners:",["Let's turn over a new leaf.","Let's wipe the slate clean."]]]};

/* add the topics to Unit 3, Section B, and link to them from related topics */
(function(){
  const u3 = TREE.children.find(u => u.id === "u3");
  const sb = u3.children.find(s => s.id === "u3b");
  if (!sb.children.includes("j5")) sb.children.push("j5", "j6");
  BOOK.g1.notes.push([3,"X","For stars on the board and class points, see Unit 3, B: Giving rewards.",[]]);
  BOOK.j4.notes.push([6,"X","See also Unit 3, B: Giving consequences.",[]]);
})();
/* Adult-class dialogues (Units 1–3). Each uses the topic's key phrases from the book. Teacher: Rina. Students: adult learners. */
const AD = {
 a1:{lines:[["T","Good evening, everyone. Come in and sit down, please."],["S","Sorry, the lift was full. Can I leave my bag here?"],["T","Sure. You can hang your jacket on the coat rack, too."],["S","Thanks. Is it OK if I keep my coat on? It's cold in here."],["T","Of course. Close the door behind you, please. We're about to start."]],note:"Adults are used to managing themselves. Keep instructions short and friendly, and treat requests like Can I…? as normal conversation."},
 a2:{lines:[["T","Good evening, everybody. How are you all today?"],["S","Tired, to be honest. Long day at work."],["T","I'm sorry to hear that. How about you, Andi?"],["S","Pretty good, thanks. And you?"],["T","I'm fine, thanks. I hope you all had a nice weekend."]],note:"Greetings with adults are real small talk. Ask follow-up questions about work and the weekend, and answer when they ask you back."},
 a3:{lines:[["T","Let me introduce myself. I'm Rina, and I'll be your English teacher for this course."],["S","Nice to meet you, Rina."],["T","It's nice to meet you all. Our lessons are on Tuesday and Thursday evenings, from seven to half past eight."],["S","Do we call you Miss Rina or just Rina?"],["T","Just Rina is fine. Now, could you tell your neighbour why you're learning English?"]],note:"Tell adults how you'd like to be addressed, explain the schedule clearly, and invite them to introduce themselves straight away."},
 a4:{lines:[["T","Let's see if everyone's here. Is anybody absent tonight?"],["S","Hendra's not here. He had to work late."],["T","OK, thanks. Lestari, you weren't here last time. Was everything all right?"],["S","Yes, I was on a business trip."],["T","Welcome back. Ask Maya to tell you what we did, and I'll send you the handout."]],note:"With adults, absences are usually about work or family. Ask politely, never demand a note, and help them catch up."},
 a5:{lines:[["S","Sorry I'm late. The traffic was terrible."],["T","That's all right. Take a seat and we can get on. We're on page 24."],["S","Thanks. What did I miss?"],["T","Just the warm-up. Dewi can fill you in at the break."]],note:"Adults are often late because of work or traffic. Keep it brief and friendly, and only raise it privately if it happens every week."},
 a6:{lines:[["T","OK, everybody. It's time to start our English lesson."],["S","One second, I'm just finishing an email."],["T","No problem. Could you put your phones on silent, please? Let's get down to work."],["T","Right. I'm looking forward to seeing what you can do this lesson."]],note:"Adults need a clear start signal but respond better to polite requests than to commands. Explain why, for example phones on silent so nobody is distracted."},
 b1:{lines:[["T","Right, everyone. Let's move on."],["T","Now we'll do another exercise. Let's have a look at exercise 3B on page 41."],["S","Can I ask the question in Indonesian first?"],["T","Try it in English. If you get stuck, I'll help you."]],note:"Mark transitions clearly with Right, OK or Moving on. Encourage adults to stay in English, but don't insist if the explanation really needs their first language."},
 b2:{lines:[["T","You have ten minutes for this. Is everything clear?"],["S","Do we write full sentences or just notes?"],["T","Just notes. Let's do the first one together so you see what I mean."],["S","OK, got it."],["T","Right. You can start."]],note:"Adults like to know exactly what is expected. Give the time limit, the format of the answer, and one example."},
 b3:{lines:[["T","What I've planned for today is the following. First, we'll go over your homework."],["T","Next, you'll read the article on page 30. After that, you'll discuss it in pairs."],["T","Finally, we'll look at some useful phrases for meetings."],["S","Will we have time for the email writing?"],["T","Towards the end, yes, if we keep to time."]],note:"Adults appreciate a lesson outline. It shows the purpose of each stage and lets them plan their energy after a long day."},
 b4:{lines:[["T","How are you getting on? Any problems?"],["S","I'm stuck on number 5."],["T","What's the problem?"],["S","I don't know which tense to use."],["T","Look at the time expression in the sentence. Which question are you on now, Andi?"]],note:"Circulate and check quietly. Adults may not want to admit difficulty in front of others, so ask individuals."},
 b5:{lines:[["T","OK, everybody. Two more minutes."],["T","Have you finished?"],["S","Almost. Just the last question."],["T","That's fine. Right, that's enough. Stop now, please. We'll have a short break before going on."]],note:"Give a time warning before stopping. With adults, a short break in a long evening lesson helps concentration."},
 c1:{lines:[["S","What time is it?"],["T","It's ten past eight. We have five more minutes."],["S","Shall we start the next exercise?"],["T","It isn't worth starting anything new. Let's do a quick review game instead."]],note:"Use spare minutes at the end for review rather than new material."},
 c2:{lines:[["T","For your homework, please do exercise 4 on page 33."],["S","When is it due?"],["T","Please send it to me by Monday. There will be a short test on this next week."],["S","Is it OK if I send it by email?"],["T","Of course. Don't forget about your homework, everyone."]],note:"Adults are busy. Keep homework realistic, give a clear deadline, and say how to hand it in."},
 c3:{lines:[["T","It's time to stop. So, today we've practised making polite requests."],["T","We'll finish the reading next time."],["S","That was useful for my job, actually."],["T","I'm glad to hear that. You've all worked very hard today. Thank you."]],note:"Summarise what was practised, link it to real use, and thank adults for their effort."},
 c4:{lines:[["T","Wait a moment, please. I have something to tell you."],["T","Next week we'll meet in room 12 instead."],["S","Is the class still at seven?"],["T","Yes, same time. And don't forget there's no class on the public holiday."]],note:"Make announcements before people start packing up, and check the key details with a question."},
 c5:{lines:[["T","That's all for today. Goodbye, everyone."],["S","Bye, Rina. See you on Thursday."],["T","See you all again on Thursday. Have a nice evening."],["S","Thanks, you too!"]],note:"A personal goodbye at the door builds rapport with adult learners too."},
 c6:{lines:[["T","Before you go, could someone switch off the projector for me?"],["S","Sure, I'll do it."],["T","Thanks. Please take all your things with you. Whose umbrella is this?"],["S","Oh, it's mine. Thanks!"]],note:"Ask adults for help politely, and thank them. Lost property questions (Whose…?) come up every week."},
 d1:{lines:[["T","Open your books at page 50, please."],["T","Don't look at the answers yet."],["S","Do we work alone?"],["T","Yes. Work on your own first, then compare with your partner."]],note:"Simple imperatives are fine with adults if your tone is friendly and you add please or a reason."},
 d2:{lines:[["T","Just try the next one. Don't worry about mistakes."],["S","I'm not sure about the grammar."],["T","Do have a go. You can check it afterwards."],["T","You are to finish this section by the end of the lesson, I'm afraid. It's for Thursday's test."]],note:"Use just to make a task feel small and do to sound encouraging. Soften must or be to with I'm afraid."},
 d3:{lines:[["T","Could you read the next paragraph, please, Hendra?"],["S","Sure."],["T","Thank you. Number 6. Yes, Maya, please."],["S","The answer is would have gone."],["T","Perfect. Would you mind writing that on the board?"]],note:"Polite requests with please, could you and would you mind are the normal register with adults."},
 e1:{lines:[["T","Can you all hear the recording at the back?"],["S","It's a bit quiet."],["T","I'll turn up the volume. Is that better?"],["S","Yes, much better."],["T","And can you all see the screen? Has everybody got the handout?"]],note:"Check sound and visibility before you start. Adults rarely complain unless you ask."},
 e2:{lines:[["T","Let's go round the room, starting with Andi."],["S","Shall I start?"],["T","Yes, go ahead."],["T","Thanks. Next one, please. Who hasn't had a turn yet?"],["S","I haven't."],["T","Go ahead, Lestari."]],note:"Give turns fairly. Adults notice if the same confident people always speak."},
 e3:{lines:[["T","Who would like to read the part of the manager?"],["S","I can do it."],["T","Thanks, Budi. Any volunteers for the customer?"],["S","I'll try."],["T","Great. Which topic would you like to discuss afterwards? You can decide."]],note:"Choice motivates adults. Let them volunteer and choose topics, but don't force shy learners to perform."},
 e4:{lines:[["T","I'd like you to work in groups of three."],["S","There are only two of us here."],["T","Could you join Dewi's group, then?"],["T","One of you is the interviewer, the other two are job applicants. Then swap roles."]],note:"Give all the instructions before groups form, and assign roles so everyone takes part."},
 f1:{lines:[["T","What's the date today?"],["S","It's the 17th of August."],["T","That's right. Happy Independence Day, everyone!"],["S","Thanks. And it's Maya's birthday too!"],["T","Happy birthday, Maya! Many happy returns."]],note:"Celebrating dates and birthdays creates a warm atmosphere, even with adults."},
 f2:{lines:[["T","Andi, I hear you have a job interview tomorrow. Good luck!"],["S","Thanks. I'm quite nervous."],["T","I'm sure you'll do well. Let us know how it goes."],["S","(next lesson) I got the job!"],["T","Congratulations! Well done!"]],note:"Adults bring real events to class. Wish them luck and follow up the next lesson."},
 f3:{lines:[["T","Here you are. Take one and pass them on, please."],["S","Thank you."],["T","Thanks for your help with the chairs, Hendra. It was very kind of you."],["S","Don't mention it."]],note:"Thank adults for their help and their ideas. Model the replies: Not at all, Don't mention it, Any time."},
 f4:{lines:[["S","Sorry, could you say that again? I didn't catch it."],["T","Of course. I said the meeting is on page 18."],["S","Pardon? Page 80?"],["T","Eighteen. One-eight. Sorry, that was my fault. I wasn't speaking clearly."]],note:"Teach adults how to ask for repetition politely. It is one of the most useful real-life skills."},
 f5:{lines:[["S","Excuse me, Rina. Could I leave ten minutes early today? I have to pick up my son."],["T","Of course. Just let me know when you go."],["T","Excuse me for a moment, everyone. Carry on with the exercise while I'm away."],["S","No problem."]],note:"Adults need to be able to ask permission politely. Model Could I…? and Is it all right if…?"},
 g1:{lines:[["T","Number 4, Maya?"],["S","He has been working here since 2019."],["T","That's right. Excellent."],["T","And the reason, Andi?"],["S","Because it continues to now."],["T","Exactly. That's the point. Well done."]],note:"Confirm correct answers clearly. With adults, specific praise matters more than big praise."},
 g2:{lines:[["S","I am agree with this idea."],["T","Nearly. Have another try. Do we need am?"],["S","I agree with this idea."],["T","That's much better. Keep it up."]],note:"Encourage self-correction rather than correcting immediately. Adults learn more when they find the mistake themselves."},
 g3:{lines:[["S","Last weekend I go to Bandung."],["T","Oh, you went to Bandung? What did you do there?"],["S","I went to visit my parents."],["T","That's nice. Has anybody else got a weekend story?"]],note:"Recast mistakes inside the conversation. It keeps adults talking without embarrassing them."},
 g4:{lines:[["T","Only two sentences? Come on, Budi, you can do better than this."],["S","I'm sorry, I was very tired."],["T","I understand. But I know you're capable of better work. Next time, try to write at least six sentences."],["S","OK, I'll try."]],note:"With adults, push gently and privately, and acknowledge their busy lives."},
 h1:{lines:[["T","Finished?"],["S","Not yet."],["T","Problems?"],["S","Just one word."],["T","Anybody else need more time?"]],note:"Short Yes/No questions keep an adult class moving without sounding bossy."},
 h2:{lines:[["T","That wasn't so difficult, was it?"],["S","No, it was OK."],["T","You've done this kind of exercise before, haven't you?"],["S","Yes, at work."]],note:"Question tags make classroom talk sound natural. Use falling tags when you expect agreement."},
 h3:{lines:[["T","Does anybody know if Hendra is coming tonight?"],["S","I think he's working late."],["T","Can you tell me if we finished page 21 last time?"],["S","Yes, we did."]],note:"Indirect questions sound more polite and are very useful for adults at work."},
 i1:{lines:[["T","It's very warm in here, isn't it?"],["S","Yes, could we turn the AC up?"],["T","Sure. Is that any better?"],["S","Much better, thanks."],["T","And can you see the screen OK, or is the light too bright?"]],note:"Ask adults whether they're comfortable. A stuffy room after work makes concentration hard."},
 i2:{lines:[["T","Be careful, there's a cable on the floor."],["S","Oh, thanks. I almost tripped."],["T","Let's move your bag so that no one trips over it."],["S","Good idea."]],note:"Short safety warnings work at every age. With adults, explain the reason."},
 i3:{lines:[["T","We need to make some space for this activity."],["S","Shall we move the tables to the side?"],["T","Yes, please. Does everyone have enough room to move?"],["S","Yes, that's fine."]],note:"Tell adults what the activity is so they can organise the space themselves."},
 i4:{lines:[["T","Could you come to the front, please, Dewi?"],["S","Me?"],["T","Yes. Stand here, facing the class, and present your idea."],["T","Thank you. You can go back to your seat now."]],note:"Some adults find coming to the front stressful. Ask politely and keep it short."},
 i5:{lines:[["T","Today we'll have a change. We need to move the desks into a circle."],["S","Could someone give me a hand with this table?"],["T","Thanks, Andi. And at the end, we have to put the furniture back, please."]],note:"Explain why you're rearranging the room, and remember to put it back at the end."},
 i6:{lines:[["T","Put your hand up if you have any questions."],["S","(raises a hand) Yes, I have one."],["T","Go ahead. Thanks, you can put your hand down."],["T","Let's see some different hands up for a change."]],note:"Many adult classes don't use hands up. Use it when you need order, for example in a quiz."},
 j1:{lines:[["T","Today we're going to find out what kind of learner you are."],["S","I think I'm a visual learner. I like charts."],["T","Do you remember better when you read a text or listen to a talk?"],["S","When I read, definitely."],["T","So the majority of you are visual learners."]],note:"Adults are interested in how they learn best. Use the results to suggest study strategies."},
 j2:{lines:[["T","Sorry to interrupt, but could I have your attention for a moment?"],["T","Look this way now, please."],["S","Sorry, we were still discussing."],["T","No problem. Thank you, that's much better."]],note:"A polite interruption works better than raising your voice in an adult class."},
 j3:{lines:[["T","Please listen to the instructions."],["T","Read the email, underline the requests, then write a reply. Are you with me?"],["S","Could you repeat the last part?"],["T","Write a reply. You'll find all the instructions on this sheet, too."]],note:"Give instructions in a clear order and put them in writing for adults who missed something."},
 j4:{lines:[["T","Hendra, could you put your phone away, please? You're disturbing the others."],["S","Sorry, it's my boss."],["T","I understand. Could you take it outside, then? We'll carry on."],["T","(after class) Is everything all right? You seemed busy today."]],note:"With adults, deal with problems politely and privately. Ask what's wrong rather than giving consequences."},
 j5:{lines:[["T","Great discussion, everyone. That's a point for each team."],["S","Who's winning?"],["T","Team A has five points and Team B has four. The winners choose the topic next week."],["S","Then we'd better keep going!"]],note:"Adults enjoy light competition too. Keep rewards simple, such as choosing a topic or a game."},
 j6:{lines:[["T","Andi, this is the third time you've been on your phone today."],["S","Sorry, it's work."],["T","I understand, but it's distracting for the group. Could we agree that phones stay away during activities?"],["S","Yes, that's fair."]],note:"With adults, agree rules together and talk about the effect on the group, not punishment."},
 k1:{lines:[["T","Let's play a game. Get into two teams."],["S","What's the game?"],["T","Listen carefully to the rules. I'll describe a word and your team guesses it."],["T","Are you ready? Team A, it's your turn. One point for this team!"]],note:"Games work with adults when the purpose is clear, for example revising vocabulary."},
 k2:{lines:[["T","It's time for a song. Do you know this song?"],["S","Yes! I listened to it a lot when I was at university."],["T","Great. Listen carefully to the words first, then sing along with the recording."],["S","Can we see the lyrics?"],["T","Of course. Follow the words on the screen."]],note:"Choose songs adults know and like. Singing is optional, but listening for the lyrics is useful practice."},
 k3:{lines:[["T","Let's act out this dialogue. Who wants to be the hotel receptionist?"],["S","I'll be the receptionist."],["T","Thanks. You have five minutes to practise."],["T","That was great. Give yourselves a clap."]],note:"Role plays based on real situations, such as hotels, meetings and phone calls, are very motivating for adults."},
 k4:{lines:[["T","You are going to prepare a poster about a tourist attraction in your city."],["S","What information should we include?"],["T","First decide what information to include, then try out different designs."],["T","Let's make the display. Stick your poster up on the wall."]],note:"Adults can produce posters, leaflets or slides. Link the product to real use."},
 k5:{lines:[["T","I have something to show you. I'll give you a clue first. You use it every day at work."],["S","A stapler?"],["T","Good guess, but no. Look at it carefully."],["S","Oh, a USB charger!"],["T","Right. How would you describe it?"]],note:"Realia makes vocabulary memorable for adults too, especially work objects."},
 l1:{lines:[["T","Could you open the window, please?"],["S","Sure."],["T","Thank you. Read the next one, would you, Maya?"],["S","OK."]],note:"Could you…? and modal tags such as would you? are the natural register with adults."},
 l2:{lines:[["T","Would you like to try the next one, Budi?"],["S","OK."],["T","I'd like you all to work with a new partner today."],["S","Why?"],["T","I want you to hear different accents and ideas."]],note:"Use would like and want with a reason, so adults understand the purpose."},
 l3:{lines:[["T","Would you mind repeating what you said?"],["S","Sure. I said the meeting was cancelled."],["T","Thanks. Do you mind if I open the window?"],["S","Not at all."],["T","And I wonder if you could explain the word schedule to the group."]],note:"Would you mind…? and I wonder if… are polite forms adults need for work English."}
};
/* Adult-class dialogues (Units 4–6). Each uses the topic's key phrases from the book. */
Object.assign(AD, {
 m1:{lines:[["T","Could you pass these handouts to the back, please?"],["S","How many each?"],["T","Take one and pass the rest on. You can keep these handouts."],["S","Great, I'll use it at work."]],note:"Adults often keep useful handouts for real life. Tell them which ones are theirs to keep."},
 m2:{lines:[["T","Has everybody got a copy?"],["S","I haven't. I forgot my book at the office."],["T","Could you share your book with Lestari today?"],["S","Sure, no problem."],["T","Thanks. Who else hasn't got a copy? You can use my copy this time."]],note:"Adults forget materials because of work, not carelessness. Solve it quickly and calmly."},
 m3:{lines:[["T","Take out your books, please. Open your books at page 49."],["S","The workbook or the coursebook?"],["T","The coursebook. You'll find the exercise at the bottom. Look at exercise 5A."],["S","Got it."]],note:"Say which book, the page and the exercise. Adults who arrive late can then find the place by themselves."},
 m4:{lines:[["T","Turn over the page."],["S","To the grammar box?"],["T","Yes. Now turn back to page 35 for a moment. Look back at the last chapter."],["S","Ah, it's the same structure."],["T","Exactly. Now turn to the next page again."]],note:"Turning back to earlier pages helps adults connect new language with what they already know."},
 m5:{lines:[["T","Have you all found the place?"],["S","Sorry, where are we?"],["T","We're on page 27, line 24. Could you show Budi where we are, Maya?"],["S","Here, Budi. Not that line, the next one."]],note:"Let adults help each other find the place. It is quicker and less embarrassing than repeating it to the whole room."},
 m6:{lines:[["T","Close your books, please. We'll do the rest from memory."],["S","Should we hand in our worksheets?"],["T","Yes. Hand in your work as you leave, please. Pile them up on my desk."],["S","Here you are."]],note:"Tell adults clearly what to keep and what to hand in before they start packing up."},
 n1:{lines:[["T","Today's text is about working from home."],["S","Oh, that's my life!"],["T","Look at the picture and the title. What do you think it will be about?"],["S","Maybe the problems of working at home."],["T","Good idea. What kind of text is this? A report or a blog post?"]],note:"Choose texts linked to adults' lives and ask them to predict before reading."},
 n2:{lines:[["T","Read it through quickly to get the main idea. You have three minutes."],["S","There are a lot of new words."],["T","It doesn't matter if you don't understand every word. While reading, try to answer these two questions."],["S","OK. And later we can look up the new words?"],["T","Yes, later you can look them up in the dictionary."]],note:"Adults often want to understand every word. Reassure them that reading for gist is a real-life skill."},
 n3:{lines:[["T","Did you get the gist?"],["S","I think so. It's about the advantages and disadvantages."],["T","Good. Can you briefly summarize the main ideas?"],["S","Working at home saves time, but people feel lonely."],["T","Exactly. Is there anything you didn't understand?"]],note:"Ask adults to summarise in their own words. It shows real understanding."},
 n4:{lines:[["T","Let's read the passage aloud. Who would like to begin?"],["S","I'll start."],["T","Thanks, Andi. Read to the end of the sentence. Stop there, please."],["T","Lestari, go on from where Andi left off."],["S","OK, from 'However'…"]],note:"Ask for volunteers to read aloud. Adults can be anxious about their pronunciation in front of others."},
 n5:{lines:[["T","Let's take a closer look at the text. Look at line 15 for a moment."],["S","'Burnout'? What's the Indonesian for this?"],["T","Kelelahan kerja, more or less. What's another way of saying this?"],["S","Being exhausted from work?"],["T","That's it."]],note:"A quick translation is fine with adults. Then ask for an English paraphrase."},
 n6:{lines:[["T","Are there any questions about this text?"],["S","Yes. What does 'commute' mean?"],["T","You met this word last time. Does anybody remember?"],["S","It's the journey to work."],["T","Right. Would you like anything else explained?"]],note:"Recycle vocabulary from earlier lessons and let other adults explain."},
 o1:{lines:[["T","I want you to do exercise 7A."],["S","What do we do exactly?"],["T","This is the way we'll do it. Watch me first."],["T","The idea of this exercise is to practise asking questions politely at work."],["S","Oh, that's useful."]],note:"Tell adults the purpose of each exercise. They are more motivated when they see the real-life use."},
 o2:{lines:[["T","Copy this down from the board."],["S","All of it?"],["T","Just the example sentences. Make a note of this and underline the new words."],["S","Can I take a photo instead?"],["T","Sure. But writing it helps you remember."]],note:"Adults often take photos of the board. Allow it, but explain the value of writing things down."},
 o3:{lines:[["T","I think you've had long enough on this. You all seem to have finished."],["S","Almost."],["T","Let's go through this exercise and check the answers."],["T","Let's see how you did."]],note:"Signal clearly that working time is over and checking has begun."},
 o4:{lines:[["T","What have you got for question 2?"],["S","Would you mind to send…"],["T","Hmm. Can anybody help?"],["S","Would you mind sending?"],["T","Yes. Did anybody have a different answer?"]],note:"Let other adults help, but ask the first learner to repeat the right answer so they finish with success."},
 o5:{lines:[["S","I have lived here since three years."],["T","Are you sure about that? Since or for?"],["S","For three years."],["T","Right, you made a small mistake. Is there another way of saying it?"],["S","Since 2023?"],["T","That's also possible."]],note:"Questions like Are you sure? give adults the chance to correct themselves."},
 o6:{lines:[["T","How did you get on?"],["S","Quite well, I think."],["T","Give yourself one point for every correct answer. How many did you get right?"],["S","Eight out of ten."],["T","Well done. Hands up if you scored more than seven."]],note:"Self-marking is fine with adults. Don't ask them to compare scores publicly if anyone seems uncomfortable."},
 p1:{lines:[["T","Is the answer A or B?"],["S","B."],["T","Would you like to work with Andi's group or Maya's group?"],["S","Andi's group."],["T","And are the reasons for the change political or economic?"],["S","Mostly economic, I think."]],note:"Or questions help weaker learners answer, and can open into real discussion with adults."},
 p2:{lines:[["T","Where did we stop last time?"],["S","Page 40, the email."],["T","Thanks. Whose turn is it to take notes for the group?"],["S","Mine."],["T","Which group would you like to join, Hendra?"]],note:"Wh- questions give adults choices and responsibility in class."},
 p3:{lines:[["T","Can anybody explain what this word means?"],["S","I think 'deadline' is the last day to finish something."],["T","Good. Do you know why this answer is better than A?"],["S","Because it's more polite."],["T","Exactly. Why do you think politeness matters in emails?"]],note:"Indirect questions sound less like a test, which adults appreciate."},
 q1:{lines:[["T","Please look at the board."],["T","Come and write the answer on the board, Dewi."],["S","Like this?"],["T","Perfect. Step aside so that everyone can see. Is the sentence on the board right?"],["S","Yes, it is."]],note:"Ask adults to write on the board only if they're comfortable. Let them choose to volunteer."},
 q2:{lines:[["T","Would someone clean the board, please?"],["S","I'll do it."],["T","Thanks. Please don't wipe the date off. And you can leave this sentence up."],["S","OK, just the examples, then."]],note:"Say clearly what should stay on the board."},
 q3:{lines:[["T","I'll just plug the projector in."],["T","Can everyone read the slide OK?"],["S","The writing is out of focus."],["T","Let's see if I can get this in focus. Is that better?"],["S","Yes, much better."]],note:"Narrate small technical problems calmly. Adults are used to this at work."},
 q4:{lines:[["T","To begin with, there'll be a short presentation. Today's topic is writing a CV."],["T","Pay particular attention to the highlighted points."],["S","Should we take notes?"],["T","You don't need to take notes. I'll share the slides afterwards."]],note:"Tell adults whether to take notes and whether they'll get the slides."},
 q5:{lines:[["T","I have a poster here. I'll reveal it slowly."],["T","What can you see in the picture?"],["S","An office… people at a meeting."],["T","What does it remind you of?"],["S","My Monday mornings!"],["T","Ha! Any other ideas?"]],note:"Visuals prompt personal responses from adults. Accept humour as real communication."},
 r1:{lines:[["T","Check that your equipment is working. Please check your headset is plugged in."],["S","I can't hear anything."],["T","Look at the control panel in front of you. Is the volume up?"],["S","Oh, now it works."],["T","Good. Press the call teacher button if you need help."]],note:"Give adults a minute to explore the equipment before the task starts."},
 r2:{lines:[["T","Today we have a short dialogue to listen to: a phone call to a hotel."],["T","You'll be able to work independently. Listen to it as many times as you like."],["S","Can I stop and repeat?"],["T","Yes, you can listen at your own pace. Then there'll be a task to complete."]],note:"Independent listening suits adults with different levels and speeds."},
 r3:{lines:[["S","My headset doesn't work."],["T","Is there a problem? Let me see."],["T","There's something wrong with the equipment. Please be patient. This will take a few moments."],["T","Maybe I could try this… Is that any better?"],["S","Yes, thanks."]],note:"Stay calm and keep the others working while you fix a technical problem."},
 s1:{lines:[["T","We'll be using the internet today. Type the address into the address bar."],["S","Then what?"],["T","Type a keyword, like 'hotel reviews', into the search field. Select one of the titles in the list."],["S","Should I save it?"],["T","Yes, bookmark the address. We'll use it next time."]],note:"Adults use computers every day but may not know the English words. Teach the language of what they already do."},
 s2:{lines:[["S","Oh dear, the document won't print."],["T","Let's check the connection. Everything looks OK."],["S","Maybe the printer is out of paper?"],["T","Good thinking. Yes, it is. I'll get some more."]],note:"Adults often solve tech problems faster than the teacher. Let them help."},
 t1:{lines:[["T","Let's go through the new words first."],["S","Can we do the role play after?"],["T","Sure. Let's not spend too long on the words, shall we?"],["T","How about this group starting the role play?"],["S","OK, we'll go first."]],note:"Let's and How about…? make suggestions sound collaborative, which suits adult classes."},
 t2:{lines:[["T","I suggest saving your work every few minutes."],["S","Should we all work on one computer?"],["T","I'd suggest not working in groups of more than three. May I suggest you make a backup copy?"],["S","Good idea."]],note:"Suggest is a polite way to guide adults without giving orders."},
 t3:{lines:[["S","I can't remember the website name."],["T","If I were you, I'd make a note of the address."],["S","And should I print everything?"],["T","I'd rather you didn't print it all out. It might be a good idea to save it as a PDF instead."]],note:"Advice phrases like If I were you… show respect for adults' own decisions."},
 v1:{lines:[["T","Now we'll do a listening exercise: a job interview."],["T","Before you listen, what do you think this will be about?"],["S","Questions about experience?"],["T","Probably. Don't expect to catch every word. Now listen again, and this time fill in the missing words."]],note:"Use real-world recordings and prepare adults by predicting the content."},
 v2:{lines:[["T","Listen and repeat: 'Could you send me the report?'"],["S","Could you send me the report?"],["T","All together now, please. Again, please, a bit louder."],["T","Now just this side of the room."]],note:"Choral repetition helps shy adults practise without being singled out."},
 v3:{lines:[["S","How is this word pronounced? 'Schedule'?"],["T","In British English it's /ˈʃedjuːl/, in American English /ˈskedʒuːl/."],["T","And don't mix up 'sheep' and 'ship'. Can you hear the difference?"],["S","Sheep… ship. Yes."],["T","Watch my mouth closely. The first one is longer."]],note:"Adults are often self-conscious about pronunciation. Focus on sounds that affect understanding."},
 v4:{lines:[["T","We'll do it like this. I'll do the first one with you so you know what I mean."],["T","First I'll say it, and then you can try: 'What do you do for a living?'"],["S","What do you do for a living?"],["T","Great. Now ask the person sitting next to you. Would you rather work in pairs or threes?"]],note:"Model the activity, then let adults choose how they work."},
 v5:{lines:[["T","Let's talk about this picture. What's he thinking about at the moment?"],["S","Maybe he's thinking about quitting his job."],["T","Interesting! Why?"],["S","He looks bored at his desk."],["T","Did you enjoy that activity? Which activity did you like best today?"]],note:"Move from controlled practice to real opinions. Adults have a lot to say about work and life."},
 v6:{lines:[["T","Today we're going to have a discussion. The topic is: should companies allow a four-day week?"],["S","Yes, because people are happier."],["T","Why do you think so? Could you give me an example?"],["S","My cousin's company tried it and productivity went up."],["T","I'm not sure what you mean by 'went up'. Can you explain?"]],note:"Adults enjoy real debates. Your role is to ask for reasons, examples and clarification."},
 w1:{lines:[["T","Go through the text and underline the adverbs."],["T","What does the word 'flexible' mean in this context?"],["S","You can choose your hours."],["T","Good. What's the corresponding noun?"],["S","Flexibility."]],note:"Revisit the text for language work after the content has been understood."},
 w2:{lines:[["T","Rearrange the sentences so that the email makes sense."],["S","Should 'Dear Mr Tan' be first?"],["T","Of course. Then fill in the blanks with the right linking words."],["S","Done. Do we match the sentences to the pictures too?"],["T","Yes, that's the last part."]],note:"Reading tasks based on real documents (emails, notices) are motivating for adults."},
 w3:{lines:[["T","Have you all got something to write with?"],["T","Now we'll do a writing exercise. Join the sentences together using 'because' or 'so'."],["S","Can you show us an example?"],["T","Follow the example on the board: 'I was late because the traffic was bad.'"]],note:"Short structured writing builds confidence before longer tasks."},
 w4:{lines:[["T","You're going to write a short report for your manager. First of all, let's brainstorm this topic."],["T","Think about who will be reading your work."],["S","My boss, so it should be formal."],["T","Exactly. Try to make an outline, then begin by drafting it. Take time to review what you've written."]],note:"Process writing (brainstorm, outline, draft, review) mirrors how adults write at work."},
 w5:{lines:[["S","How do you spell 'necessary'?"],["T","Spell it in English, please. Then check: have you spelt it right?"],["S","N-E-C-E-S-S-A-R-Y."],["T","Correct. And in your email, you need a comma here, after 'However'."],["S","Oh, and there's an apostrophe missing in 'its'?"],["T","Not here. 'Its' is correct."]],note:"Point out spelling and punctuation in authentic tasks like emails, where accuracy matters to adults."},
 x1:{lines:[["T","How would you describe national identity?"],["S","Language, food, traditions…"],["T","Can we group these ideas under two or three headings?"],["S","Culture and history, maybe."],["T","Good. What's the difference between them?"]],note:"Adults can handle abstract topics. Help them organise ideas with classifying language."},
 x2:{lines:[["T","How would you define 'work-life balance'?"],["S","It's when you have time for work and for your family."],["T","Can anyone give me a more precise definition?"],["S","It's the balance between the time you spend working and your personal life."],["T","Good. What is a good example of this?"],["S","For example, not answering emails at the weekend."]],note:"Practise defining and giving examples. These are key skills for meetings and presentations."},
 x3:{lines:[["T","How do you apply for a visa? What happens first?"],["S","First you fill in the form online."],["T","What would be the next step?"],["S","You book an appointment and bring your documents."],["T","And what was the result when you did it?"],["S","It took three weeks."]],note:"Describing real processes from adults' lives gives sequencing language a purpose."},
 x4:{lines:[["T","Look at this chart. What percentage of the employees agreed?"],["S","About 60 percent."],["T","What changes have taken place since 2020?"],["S","There has been a steady increase in remote work."],["T","What trend can you see?"]],note:"Adults often present data at work. Practise reading charts and describing trends."},
 x5:{lines:[["T","Why does traffic get worse every year?"],["S","More people buy cars."],["T","What would be a reasonable explanation for that?"],["S","Public transport isn't good enough."],["T","What's your hypothesis? What if there were a new train line? What then?"]],note:"Hypothesising (What if…?) lets adults discuss real problems in their city."},
 x6:{lines:[["T","What does the text say about online shopping?"],["S","That it's bad for small shops."],["T","What arguments are put forward?"],["S","Prices and convenience."],["T","What does the writer think? Is the writer biased?"],["S","Yes, I think he works for a shop association."]],note:"Critical reading helps adults with real news and reports."},
 x7:{lines:[["T","What other opinions are there about working from home?"],["S","Some managers think people work less."],["T","What are the pros and cons?"],["S","Pros: no commute. Cons: less teamwork."],["T","How does this change your opinion?"]],note:"Encourage adults to consider views they disagree with before deciding."},
 y1:{lines:[["T","What was your holiday like?"],["S","Great. We went to Yogyakarta."],["T","What's Yogyakarta like?"],["S","Busy, but very friendly."],["T","What else did you do? Anything else?"]],note:"What…like? and else invite longer answers in real conversation."},
 y2:{lines:[["T","What time does your meeting start tomorrow?"],["S","At nine."],["T","How long will it take?"],["S","About two hours."],["T","Which year did you start this job?"],["S","In 2021."]],note:"Precise Wh- questions are essential for adults arranging things at work."},
 y3:{lines:[["T","You work in… what department?"],["S","Marketing."],["T","And you joined the company in…?"],["S","In 2019."],["T","And this tool here is called a…?"],["S","A spreadsheet!"],["T","Anybody else?"]],note:"Prompting with an unfinished sentence helps adults find words without feeling tested."}
});
/* New level system: Preschool (ls), Kids (sk), Teens (st), Adults (sp). Teens take the former older-teen dialogues; Adults use AD. */
LEVELS.splice(0, LEVELS.length,
  {id:"ls", name:"Preschool", age:"3–6 yrs", cefr:"", short:"PS"},
  {id:"sk", name:"Kids", age:"7–12 yrs", cefr:"", short:"KD"},
  {id:"st", name:"Teens", age:"13–17 yrs", cefr:"", short:"TN"},
  {id:"sp", name:"Adults", age:"18+ yrs", cefr:"", short:"AD"});
for (const k in R) {
  const lv = R[k].levels; if (!lv) continue;
  if (lv.sp) { lv.st = lv.sp; lv.st.note = lv.st.note.replace(/Older teens/g, "Teens").replace(/older teens/g, "teens"); }
  if (AD[k]) lv.sp = AD[k]; else console.warn("No adult dialogue for", k);
}
